 for(const e of ordered){const {a,b}=e;const pts=[point(a.pos,authorR),point(mid(a.s),subR)];if(a.s!==b.s){pts.push(point(mid(a.f),fieldR));if(a.f!==b.f)pts.push([cx,cy],point(mid(b.f),fieldR));pts.push(point(mid(b.s),subR));}pts.push(point(b.pos,authorR));const d=basis(pts);const path=svg('path',{class:'cb-link',d,stroke:e.cross_field?cross:same,'stroke-width':weight(e),'stroke-linecap':'round'});layer.append(path);const g=svg('g'),hit=svg('path',{class:'cb-hit',d,'stroke-width':Math.max(4,weight(e)+1)});g.append(hit);hotspots.append(g);bind(hit,edgeItem(e),()=>edgeTip(e));const over=svg('path',{class:'cb-link',d,'stroke-linecap':'round',display:'none'});active.append(over);edgeMarks.set(e.id,{g,path,over});}
