 for(const a of authors){const [x,y]=point(a.pos,authorR),g=svg('g',{class:'cb-mark'});const hit=svg('circle',{cx:x,cy:y,r:Math.min(8,Math.max(4,authorR*tau/cursor*.54)),fill:'transparent'});const dot=svg('circle',{cx:x,cy:y,r:a.links.length?2.65:2.9,fill:a.links.length?band:C.background||'#fff',stroke:a.links.length?C.background||'#fff':band,'stroke-width':a.links.length?.7:1.2,'pointer-events':'none'});g.append(hit,dot);marks.append(g);bind(g,authorItem(a),()=>authorTip(a),true);authorMarks.set(a.author_id,{g,dot});}
