 if(!it){detail.append(html('div','cb-eyebrow','Reading the circle'),html('p','','Outer bands: fields. Inner segments: subfields. Dots: researchers.'),html('p','','Thicker curves mean more shared works (square-root scale). Select a researcher to list their visible collaborators.'));return;}
